package com.login.demo.controller.api;
import com.login.demo.model.entity.Menu; import com.login.demo.repository.MenuRepository; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/menu") public class MenuApiController { private final MenuRepository repo; public MenuApiController(MenuRepository repo){this.repo=repo;} @GetMapping public List<Menu> listar(){return repo.findAll();} @GetMapping("/{id}") public Optional<Menu> ver(@PathVariable Integer id){return repo.findById(id);} @PostMapping public Menu crear(@RequestBody Menu m){return repo.save(m);} @PutMapping("/{id}") public Menu actualizar(@PathVariable Integer id,@RequestBody Menu m){m.setId(id);return repo.save(m);} @DeleteMapping("/{id}") public void eliminar(@PathVariable Integer id){repo.deleteById(id);} }
